DROP TABLE IF EXISTS transactions; DROP TABLE IF EXISTS auth_tokens; DROP TABLE IF EXISTS tickets; DROP TABLE IF EXISTS users; DROP TABLE IF EXISTS bookings; DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS seats; DROP TABLE IF EXISTS movies; DROP TABLE IF EXISTS halls; DROP TABLE IF EXISTS cinemas;
CREATE TABLE cinemas (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, address VARCHAR(200) NOT NULL, description VARCHAR(300), active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE halls (id INT AUTO_INCREMENT PRIMARY KEY, cinema_id INT NOT NULL, name VARCHAR(60) NOT NULL, screen_w FLOAT NOT NULL, screen_h FLOAT NOT NULL, FOREIGN KEY (cinema_id) REFERENCES cinemas(id));
-- x/y/z — метры в системе зала: x вправо, y вверх (уровень пола), z от поля вглубь. Те же значения использует и схема, и 3D.
CREATE TABLE seats (id INT AUTO_INCREMENT PRIMARY KEY, hall_id INT NOT NULL, row_num INT NOT NULL, seat_num INT NOT NULL, seat_type ENUM('standard','sofa') NOT NULL, label VARCHAR(40) NOT NULL, x FLOAT NOT NULL, y FLOAT NOT NULL, z FLOAT NOT NULL, price INT NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, UNIQUE KEY (hall_id,row_num,seat_num), FOREIGN KEY (hall_id) REFERENCES halls(id));
CREATE TABLE movies (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(120) NOT NULL, description VARCHAR(400), duration INT NOT NULL, genre VARCHAR(60), hue INT NOT NULL DEFAULT 10, year SMALLINT, country VARCHAR(60), rating DECIMAL(3,1), age VARCHAR(4), premiere DATE NULL, trailer_url VARCHAR(300) NULL);
CREATE TABLE sessions (id INT AUTO_INCREMENT PRIMARY KEY, cinema_id INT NOT NULL, hall_id INT NOT NULL, movie_id INT NOT NULL, starts_at DATETIME NOT NULL, format VARCHAR(30) DEFAULT '2D', KEY (cinema_id,starts_at), FOREIGN KEY (hall_id) REFERENCES halls(id), FOREIGN KEY (movie_id) REFERENCES movies(id));
CREATE TABLE bookings (id INT AUTO_INCREMENT PRIMARY KEY, session_id INT NOT NULL, buyer_name VARCHAR(80) NOT NULL, buyer_email VARCHAR(120), total_price INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'paid', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (session_id) REFERENCES sessions(id));
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, pass_hash VARCHAR(200) NOT NULL, balance INT NOT NULL DEFAULT 0 CHECK (balance >= 0), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auth_tokens (token CHAR(64) PRIMARY KEY, user_id INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
-- live=1 у действующего билета, NULL у возвращённого: NULL не участвует в UNIQUE, поэтому место после возврата снова продаётся
CREATE TABLE tickets (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, session_id INT NOT NULL, seat_id INT NOT NULL, price INT NOT NULL, token CHAR(36) NOT NULL UNIQUE, user_id INT NULL, status VARCHAR(20) NOT NULL DEFAULT 'paid', live TINYINT NULL DEFAULT 1, UNIQUE KEY one_live_seat (session_id,seat_id,live), FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (seat_id) REFERENCES seats(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE transactions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, type ENUM('topup','purchase','refund') NOT NULL, amount INT NOT NULL, method VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'success', ticket_id INT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (ticket_id) REFERENCES tickets(id));
